        {tier_1_candidates.length > 0 && (
          <ReportSection title="Tier 1 Candidates" icon={TrendingUp}>
            <div className="space-y-2">
              {tier_1_candidates.map((c) => (
                <MutationRow key={c.position} candidate={c} />
