export function isPDBAnalysisResult(data: unknown): data is PDBAnalysisData {
  if (!data || typeof data !== 'object') return false
  const d = data as Record<string, unknown>
  return Array.isArray(d.chains) && typeof d.total_atoms === 'number'
}

import { useMemo } from 'react'
import { Box, Layers, Gauge, Activity, Hash } from 'lucide-react'

interface ChainData {
  chain_id: string
  coordinates: [number, number, number][]
  num_residues?: number
}

interface SymmetryResult {
  chains: ChainData[]
  num_chains: number
  symmetry: string
  symmetry_label: string
  symmetry_family?: string
  total_residues?: number
}

interface DesignResult {
  design_id: number
  length: number
  monomer_length: number
  symmetry_result: SymmetryResult
  mean_plddt: number
  radius_of_gyration: number
  ss_composition_pct: Record<string, number>
  interface_score: number
  backbone_rmsd_estimate: number
}

interface RFdiffusionData {
  designs: DesignResult[]
  parameters: {
    length: number
    num_designs: number
    target: string
    symmetry_type: string
    symmetry_label: string
    num_subunits: number
    monomer_length: number
    helix_pct: number
    sheet_pct: number
  }
  target_notes: string
  method: string
  top_design?: {
    design_id: number
    mean_plddt: number
    rg: number
    ss_composition: Record<string, number>
    backbone_rmsd: number
    interface_score: number
    symmetry: SymmetryResult
  }
}

export function isRFdiffusionResult(data: unknown): data is RFdiffusionData {
  if (!data || typeof data !== 'object') return false
  const d = data as Record<string, unknown>
  return (
    Array.isArray(d.designs) &&
    typeof d.parameters === 'object' &&
    d.parameters !== null &&
    typeof (d.parameters as Record<string, unknown>).symmetry_type === 'string'
  )
}

function MetricRow({ icon: Icon, label, value, unit, color }: {
  icon: typeof Box; label: string; value: string | number; unit?: string; color?: string
}) {
  return (
    <div className="flex items-center justify-between py-1.5 border-b border-border/50 last:border-0">
      <div className="flex items-center gap-1.5">
        <Icon className={`w-3 h-3 ${color || 'text-muted-foreground'}`} />
        <span className="text-[11px] text-muted-foreground">{label}</span>
      </div>
      <span className="text-[11px] font-mono font-medium">
        {value}{unit && <span className="text-muted-foreground ml-0.5">{unit}</span>}
      </span>
    </div>
