                  <th className="px-4 py-3 font-medium">PDB</th>
                  <th className="px-4 py-3 font-medium">Residue</th>
                  <th className="px-4 py-3 font-medium">UniProt</th>
                  <th className="px-4 py-3 font-medium">Confidence</th>
