                    <td className="px-4 py-3 text-xs font-mono text-muted-foreground">
                      {row.pdb_residue_no}
                      {row.insertion_code || ''}
                    </td>
                    <td className="px-4 py-3 text-sm">
                      {row.residue_name} ({row.residue_aa})
