export function isStructureMappingResult(data: unknown): data is StructureMappingData {
  if (!data || typeof data !== 'object') return false
  const record = data as Record<string, unknown>
  return Array.isArray(record.mappings) && typeof record.status === 'string'
}

import { Boxes, Database, Search, ShieldAlert } from 'lucide-react'
import {
  ReportBadge,
  ReportBody,
  ReportHeader,
  ReportMetricCard,
  ReportMetricGrid,
  ReportPanel,
  ReportSection,
  ReportShell,
} from '@/components/analysis/ReportShell'

interface QueryStructureSummary {
  chain_count?: number
  total_residues?: number
  total_atoms?: number
}

interface StructureSearchResult {
  target_id?: string | null
  template_id?: string | null
  title?: string | null
  source?: string | null
  score?: number | string | null
  rmsd?: number | string | null
  tm_score?: number | string | null
  identity?: number | string | null
  description?: string | null
}

interface StructureSearchData {
  found: boolean
  status: string
  error_code?: string
  warning?: string
  database?: string
  backend?: string
  database_path?: string
  results_count?: number
  results: StructureSearchResult[]
  query_structure?: QueryStructureSummary
  cache?: {
    hit?: boolean
    stale?: boolean
  }
}

function renderHitTitle(hit: StructureSearchResult, index: number) {
  return hit.title || hit.template_id || hit.target_id || `Hit ${index + 1}`
