export function StructureSearchResultCard({ data }: { data: StructureSearchData }) {
  return (
    <ReportShell>
      <ReportHeader
        icon={Search}
        title="Structure Search"
        subtitle={`${data.database || 'unknown database'} · ${data.status}`}
        badge={
