            {data.results_count ?? data.results.length} hits
          </ReportBadge>
        }
      />
      <ReportBody>
        {data.warning ? (
          <ReportPanel tone="warning" className="text-xs leading-6 text-muted-foreground">
            {data.warning}
          </ReportPanel>
        ) : null}

        <ReportSection title="Query Structure" icon={Database}>
          <ReportMetricGrid>
            <ReportMetricCard label="Chains" value={data.query_structure?.chain_count ?? 0} tone="info" />
            <ReportMetricCard label="Residues" value={data.query_structure?.total_residues ?? 0} />
            <ReportMetricCard label="Atoms" value={data.query_structure?.total_atoms ?? 0} />
            <ReportMetricCard
              label="Backend"
              value={data.backend || 'unknown'}
              tone={data.backend === 'summary_only' ? 'warning' : data.backend === 'local_cli' ? 'success' : 'info'}
            />
            <ReportMetricCard
              label="Cache"
              value={data.cache?.stale ? 'Stale' : data.cache?.hit ? 'Hit' : 'Fresh'}
              tone={data.cache?.stale ? 'warning' : data.cache?.hit ? 'info' : 'neutral'}
            />
          </ReportMetricGrid>
        </ReportSection>

        {data.database_path ? (
          <ReportPanel tone="info" className="text-xs leading-6 text-muted-foreground">
            Foldseek DB path: <code className="font-mono">{data.database_path}</code>
          </ReportPanel>
        ) : null}

        {data.results.length > 0 ? (
          <ReportSection title="Top Hits" icon={Boxes}>
            <div className="space-y-3">
              {data.results.slice(0, 5).map((hit, index) => (
                <ReportPanel key={`${hit.template_id || hit.target_id || index}`} tone="success" className="space-y-2">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="text-sm font-medium">{renderHitTitle(hit, index)}</span>
                    {hit.source ? <ReportBadge tone="info">{hit.source}</ReportBadge> : null}
                    {hit.template_id ? <ReportBadge tone="neutral">{hit.template_id}</ReportBadge> : null}
                  </div>
                  <div className="grid gap-2 text-xs text-muted-foreground sm:grid-cols-2 lg:grid-cols-4">
                    <div>score: {hit.score ?? 'N/A'}</div>
                    <div>TM-score: {hit.tm_score ?? 'N/A'}</div>
                    <div>RMSD: {hit.rmsd ?? 'N/A'}</div>
                    <div>identity: {hit.identity ?? 'N/A'}</div>
                  </div>
                  {hit.description ? (
                    <p className="text-xs leading-6 text-muted-foreground">{hit.description}</p>
                  ) : null}
                </ReportPanel>
              ))}
            </div>
          </ReportSection>
        ) : null}

        {data.results.length === 0 ? (
          <ReportSection title="Current Status" icon={ShieldAlert}>
            <ReportPanel tone={data.status === 'degraded' ? 'warning' : 'neutral'} className="text-xs leading-6 text-muted-foreground">
              No structural hits were returned yet.
              {data.backend === 'summary_only'
                ? ' Current response is summary-only fallback, which means the structure was parsed but Foldseek search was not executed.'
                : ' Foldseek ran but did not return a matching hit in the current database.'}
            </ReportPanel>
          </ReportSection>
        ) : null}
      </ReportBody>
    </ReportShell>
  )
}

export function isStructureSearchResult(data: unknown): data is StructureSearchData {
  if (!data || typeof data !== 'object') return false
  const record = data as Record<string, unknown>
  return Array.isArray(record.results) && 'status' in record && 'query_structure' in record
}

import { useState, useEffect } from 'react'
import { Dna, FileText, Table2, Loader2 } from 'lucide-react'
import { ProteinViewer } from '@/components/viewer/ProteinViewer'
import { authFetch, normalizeFileDownloadUrl } from '@/lib/api'

interface Props {
  fileName: string
  fileType: string
  content?: string
  fileUrl?: string
}

export function FileViewer({ fileName, fileType, content, fileUrl }: Props) {
  const [pdbContent, setPdbContent] = useState<string | null>(content || null)
  const [loading, setLoading] = useState(false)

  const isPDB = fileType.includes('pdb') || fileName.endsWith('.pdb') || fileName.endsWith('.cif')
  const isFasta = fileType.includes('fasta') || fileName.endsWith('.fasta') || fileName.endsWith('.fa')
  const isCSV = fileType.includes('csv') || fileName.endsWith('.csv')

  useEffect(() => {
    if (isPDB && !content && fileUrl) {
      setLoading(true)
      authFetch(normalizeFileDownloadUrl(fileUrl))
        .then((r) => r.text())
        .then((text) => setPdbContent(text))
        .catch(() => setPdbContent(null))
        .finally(() => setLoading(false))
    }
  }, [isPDB, content, fileUrl])

  return (
    <div className="border border-border rounded-xl overflow-hidden">
      {/* Header */}
      <div className="flex items-center gap-2 px-4 py-2.5 bg-secondary/50 border-b border-border">
        {isPDB ? (
          <Dna className="w-4 h-4 text-blue-500" />
        ) : isFasta ? (
          <FileText className="w-4 h-4 text-green-500" />
        ) : isCSV ? (
          <Table2 className="w-4 h-4 text-orange-500" />
        ) : (
          <FileText className="w-4 h-4 text-muted-foreground" />
        )}
        <span className="text-sm font-medium truncate">{fileName}</span>
        <span className="text-[10px] text-muted-foreground bg-secondary px-1.5 py-0.5 rounded ml-auto">
          {isPDB ? 'PDB' : isFasta ? 'FASTA' : isCSV ? 'CSV' : 'FILE'}
        </span>
      </div>

      {/* Content */}
      <div className="p-3">
        {isPDB ? (
          loading ? (
            <div className="flex items-center justify-center py-16">
              <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
            </div>
          ) : pdbContent ? (
            <ProteinViewer pdbData={pdbContent} height={300} />
          ) : (
            <div className="bg-secondary rounded-lg p-8 text-center">
              <Dna className="w-12 h-12 mx-auto mb-2 text-muted-foreground" />
              <p className="text-sm text-muted-foreground">No structure data available</p>
            </div>
          )
        ) : isFasta ? (
          <pre className="text-xs font-mono bg-secondary rounded-lg p-3 overflow-x-auto max-h-60 overflow-y-auto">
            <code>{content || '>example_sequence\nMKAILVVLLYTFTLPANAS...'}</code>
          </pre>
        ) : (
          <div className="text-xs text-muted-foreground text-center py-4">
            {content ? (
              <pre className="text-left font-mono bg-secondary rounded-lg p-3 overflow-x-auto max-h-60">{content}</pre>
            ) : (
              'File preview not available for this format'
            )}
          </div>
        )}
      </div>
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import { useTranslation } from 'react-i18next'
import { Search, MessageSquare } from 'lucide-react'
import { useChatStore } from '@/stores/chat'

interface Props {
  open: boolean
  onClose: () => void
}

export function SearchDialog({ open, onClose }: Props) {
  const { t } = useTranslation()
  const conversations = useChatStore((s) => s.conversations)
  const selectConversation = useChatStore((s) => s.selectConversation)
  const inputRef = useRef<HTMLInputElement>(null)
  const [query, setQuery] = useState('')

  // Focus input and reset query when opened
  useEffect(() => {
    if (open) {
      setQuery('')
      // Small delay to ensure the input is rendered
      requestAnimationFrame(() => inputRef.current?.focus())
    }
  }, [open])

  // Close on Escape (handled by keydown)
  useEffect(() => {
    if (!open) return
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose()
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [open, onClose])

  const filtered = query.trim()
    ? conversations.filter((c) =>
        c.title.toLowerCase().includes(query.toLowerCase())
      )
    : conversations.slice(0, 5)

  const handleSelect = (id: string) => {
    selectConversation(id)
    onClose()
  }

  if (!open) return null

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center pt-[15vh]">
      {/* Backdrop */}
      <div className="fixed inset-0 bg-black/50" onClick={onClose} />

      <div className="relative bg-card border border-border rounded-xl shadow-2xl w-full max-w-lg overflow-hidden">
        {/* Search input */}
        <div className="flex items-center gap-2 px-4 py-3 border-b border-border">
          <Search className="w-4 h-4 text-muted-foreground shrink-0" />
          <input
            ref={inputRef}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder={t('search.placeholder')}
            className="flex-1 bg-transparent text-sm focus:outline-none"
          />
          <kbd className="text-[10px] px-1.5 py-0.5 rounded bg-secondary text-muted-foreground font-mono shrink-0">
            ESC
          </kbd>
        </div>

        {/* Results */}
        {filtered.length > 0 ? (
          <div className="max-h-64 overflow-y-auto">
            {!query.trim() && (
              <div className="px-4 py-2 text-[11px] font-medium text-muted-foreground uppercase tracking-wider">
                {t('search.recentConversations')}
              </div>
            )}
            {filtered.map((conv) => (
              <button
                key={conv.id}
                onClick={() => handleSelect(conv.id)}
                className="w-full flex items-center gap-3 px-4 py-2.5 text-sm hover:bg-secondary transition-colors text-left"
              >
                <MessageSquare className="w-4 h-4 text-muted-foreground shrink-0" />
                <span className="truncate">{conv.title}</span>
              </button>
            ))}
          </div>
        ) : query.trim() ? (
          <div className="p-6 text-center">
            <p className="text-sm text-muted-foreground">
              {t('search.noResults')}
            </p>
          </div>
        ) : (
          <div className="p-4 text-xs text-muted-foreground text-center">
            {t('search.hint')}
          </div>
        )}
      </div>
    </div>
  )
}

import { useCallback, useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import { Activity, AlertTriangle, Building2, Database, Download, KeyRound, Loader2, ShieldCheck, UserCog, Users } from 'lucide-react'
import { api, ApiError, type AdminTaskAuditFilters, type AdminUser, type DeployDataImportRequest, type DeployDataReadiness, type Organization, type PermissionAudit, type ToolTaskAudit, type ToolTaskAuditSummary } from '@/lib/api'
import { useAuthStore } from '@/stores/auth'

type LoadState = 'idle' | 'loading' | 'ready' | 'error'

function formatTime(value?: string | null) {
  if (!value) return '—'
  try {
    return new Date(value).toLocaleString()
  } catch {
    return value
  }
}

function roleLabel(role: string) {
  return role === 'admin' ? '管理员' : '研发用户'
}

function formatBytes(value?: number | null) {
  if (!value) return '0 B'
  if (value < 1024) return `${value} B`
  if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KB`
  if (value < 1024 * 1024 * 1024) return `${(value / 1024 / 1024).toFixed(1)} MB`
  return `${(value / 1024 / 1024 / 1024).toFixed(1)} GB`
}

function statusClass(status: string) {
  if (status === 'ready') return 'bg-emerald-100 text-emerald-700'
  if (status === 'demo') return 'bg-amber-100 text-amber-700'
  if (status === 'empty') return 'bg-slate-100 text-slate-600'
  return 'bg-red-100 text-red-700'
}

function formatDuration(seconds?: number | null) {
  if (seconds == null) return '—'
  if (seconds < 60) return `${seconds}s`
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m ${seconds % 60}s`
  return `${Math.floor(seconds / 3600)}h ${Math.floor((seconds % 3600) / 60)}m`
}

function cleanAuditFilters(filters: AdminTaskAuditFilters): AdminTaskAuditFilters {
  return Object.fromEntries(
    Object.entries(filters).filter(([, value]) => value !== undefined && value !== '' && value !== false)
  ) as AdminTaskAuditFilters
}

